// RouteAssignment model
// Persists the assignment of a route (generated by optimization) to a vehicle and driver.

const mongoose = require('mongoose');
const { ROUTE_ASSIGNMENT_STATUS } = require('../config/constants'); // we will define enum inline if not present

const routeAssignmentSchema = new mongoose.Schema(
  {
    routeId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Route',
      required: true,
      index: true,
    },
    vehicleId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Vehicle',
      required: true,
      index: true,
    },
    driverId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Driver',
      required: true,
      index: true,
    },
    startTime: { type: Date, required: true },
    expectedEndTime: { type: Date, required: true },
    status: {
      type: String,
      enum: ['PENDING', 'DISPATCHED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED'],
      default: 'PENDING',
    },
    notes: { type: String },
  },
  {
    timestamps: true,
    toJSON: {
      transform: (doc, ret) => {
        ret.id = ret._id.toString();
        delete ret._id;
        delete ret.__v;
        return ret;
      },
    },
  }
);

module.exports = mongoose.model('RouteAssignment', routeAssignmentSchema);
